96	// ---------------------------------------------------------------------------
97	// Folders
98	// ---------------------------------------------------------------------------
99	
100	/** List the mailbox's folders with unread/total counts and their role. */
101	export async function listFolders(mailboxAddress?: string): Promise<MailFolder[]> {
102	  const { cred } = await resolveMailbox(mailboxAddress);
103	  return withImap(cred, async (client) => {
104	    const list = await client.list({ statusQuery: { messages: true, unseen: true } });
105	    const folders: MailFolder[] = [];
106	    for (const f of list) {
107	      // Skip containers that can't hold messages.
108	      if (f.flags?.has("\\Noselect")) continue;
109	      folders.push({
110	        path: f.path,
111	        name: f.name || f.path,
112	        role: folderRole(f.path, f.specialUse),
113	        unread: f.status?.unseen ?? 0,
114	        total: f.status?.messages ?? 0,
115	      });
116	    }
117	    // Stable, useful ordering: known roles first, then custom alphabetically.
118	    const order: Record<string, number> = { inbox: 0, sent: 1, drafts: 2, archive: 3, junk: 4, trash: 5, custom: 6 };
119	    folders.sort((a, b) => (order[a.role] - order[b.role]) || a.name.localeCompare(b.name));
120	    return folders;
121	  });
122	}
