316	/**
317	 * Send a message from the user's own mailbox over SMTP submission, append a copy
318	 * to Sent, and (for replies) thread it + flag the original \Answered.
319	 */
320	export async function sendMessage(
321	  payload: SendPayload,
322	  mailboxAddress?: string,
323	): Promise<{ ok: boolean; error?: string }> {
324	  const { user, cred } = await resolveMailbox(mailboxAddress);
325	  enforceRateLimit(`mail:send:burst:${user.id}`, { max: 5, windowMs: 60 * 1000 });
326	  enforceRateLimit(`mail:send:${user.id}`, { max: 60, windowMs: 60 * 60 * 1000 });
327	
328	  const to = parseRecipients(payload.to);
329	  const cc = parseRecipients(payload.cc);
330	  const bcc = parseRecipients(payload.bcc);
331	  const invalid = [...to.invalid, ...cc.invalid, ...bcc.invalid];
332	  if (invalid.length) return { ok: false, error: `Invalid recipient(s): ${invalid.join(", ")}` };
333	  if (to.list.length === 0) return { ok: false, error: "Add at least one recipient." };
334	  if (!payload.subject?.trim() && !payload.text?.trim() && !payload.html?.trim()) {
335	    return { ok: false, error: "Nothing to send — add a subject or a message." };
336	  }
337	
338	  try {
339	    // Look up threading headers when this is a reply.
340	    let inReplyTo: string | undefined;
341	    let references: string | undefined;
342	    if (payload.inReplyToUid && payload.replyFolder) {
343	      try {
344	        await withMailbox(cred, payload.replyFolder, async (client) => {
345	          const orig = await client.fetchOne(String(payload.inReplyToUid), { uid: true, envelope: true }, { uid: true });
346	          if (orig && orig.envelope?.messageId) {
347	            inReplyTo = orig.envelope.messageId;
348	            references = orig.envelope.messageId;
349	          }
350	          // Mark the message we're replying to as answered (best effort).
351	          try {
352	            await client.messageFlagsAdd(String(payload.inReplyToUid), ["\\Answered"], { uid: true });
353	          } catch {
354	            /* ignore */
355	          }
356	        });
357	      } catch {
358	        /* original not found — send without threading headers */
359	      }
360	    }
361	
362	    // Compile the message once so the exact bytes are both sent and saved to Sent.
363	    const composer = nodemailer.createTransport({ streamTransport: true, buffer: true, newline: "\r\n" });
364	    const built = await composer.sendMail({
365	      from: cred.address,
366	      to: to.list,
367	      cc: cc.list.length ? cc.list : undefined,
368	      bcc: bcc.list.length ? bcc.list : undefined,
369	      subject: payload.subject || "",
370	      text: payload.text || undefined,
371	      html: payload.html || undefined,
372	      inReplyTo,
373	      references,
374	    });
375	    const raw = built.message as Buffer;
376	
377	    const smtp = nodemailer.createTransport({
378	      host: MAIL_SMTP_HOST,
379	      port: MAIL_SMTP_PORT,
380	      secure: MAIL_SMTP_PORT === 465,
381	      requireTLS: MAIL_SMTP_PORT !== 465,
382	      tls: { servername: MAIL_TLS_SERVERNAME, rejectUnauthorized: false },
383	      auth: { user: cred.address, pass: cred.password },
384	    });
385	    await smtp.sendMail({ envelope: built.envelope, raw });
386	
387	    // Save a copy to Sent (best effort — the message already went out).
388	    try {
389	      await withImap(cred, async (client) => {
390	        const sentPath = await findSentPath(client);
391	        await client.append(sentPath, raw, ["\\Seen"]);
392	      });
393	    } catch {
394	      /* Sent append failed — not fatal */
395	    }
396	
397	    return { ok: true };
398	  } catch (e) {
399	    return { ok: false, error: String((e as Error)?.message ?? e).slice(0, 300) };
400	  }
401	}
402	
403	// ---------------------------------------------------------------------------
404	// Flags / move / delete
405	// ---------------------------------------------------------------------------
406	
407	/** Set or clear the \Seen or \Flagged flag on a message. */
408	export async function setFlag(
409	  folder: string,
410	  uid: number,
411	  flag: "seen" | "flagged",
412	  value: boolean,
413	  mailboxAddress?: string,
414	): Promise<void> {
415	  const { user, cred } = await resolveMailbox(mailboxAddress);
416	  enforceRateLimit(`mail:flag:${user.id}`, { max: 240, windowMs: 60 * 1000 });
417	  const imapFlag = flag === "seen" ? "\\Seen" : "\\Flagged";
418	  await withMailbox(cred, folder, async (client) => {
419	    if (value) await client.messageFlagsAdd(String(uid), [imapFlag], { uid: true });
420	    else await client.messageFlagsRemove(String(uid), [imapFlag], { uid: true });
421	  });
422	}
423	
424	/** Move a message from one folder to another. */
425	export async function moveMessage(
426	  folder: string,
427	  uid: number,
428	  toFolder: string,
429	  mailboxAddress?: string,
430	): Promise<void> {
431	  const { user, cred } = await resolveMailbox(mailboxAddress);
432	  enforceRateLimit(`mail:move:${user.id}`, { max: 120, windowMs: 60 * 1000 });
433	  await withMailbox(cred, folder, async (client) => {
434	    await client.messageMove(String(uid), toFolder, { uid: true });
435	  });
436	}
437	
438	/** Delete a message: move to Trash, or permanently expunge if already in Trash. */
439	export async function deleteMessage(folder: string, uid: number, mailboxAddress?: string): Promise<void> {
440	  const { user, cred } = await resolveMailbox(mailboxAddress);
441	  enforceRateLimit(`mail:delete:${user.id}`, { max: 120, windowMs: 60 * 1000 });
442	
443	  await withImap(cred, async (client) => {
444	    // Determine the Trash folder path.
445	    let trashPath = "Trash";
446	    try {
447	      const list = await client.list();
448	      const trash = list.find((f) => folderRole(f.path, f.specialUse) === "trash");
449	      if (trash) trashPath = trash.path;
450	    } catch {
451	      /* fall back to "Trash" */
452	    }
453	
454	    const inTrash = folderRole(folder) === "trash" || folder === trashPath;
455	    const lock = await client.getMailboxLock(folder);
456	    try {
457	      if (inTrash) {
458	        await client.messageDelete(String(uid), { uid: true });
459	      } else {
460	        await client.messageMove(String(uid), trashPath, { uid: true });
461	      }
462	    } finally {
463	      lock.release();
464	    }
465	  });
466	}
