199	// ---------- DKIM ----------
200	
201	/**
202	 * Fetch the DKIM public-key TXT value for a domain from Mailcow
203	 * (`GET /api/v1/get/dkim/<domain>`). Mailcow returns an object carrying the
204	 * ready-to-publish TXT in `dkim_txt` (selector `dkim`). Returns the TXT string,
205	 * or null when the domain has no DKIM key yet or the shape is unexpected.
206	 *
207	 * Throws MailcowError only when the integration is unreachable/errors — callers
208	 * that must stay tolerant wrap this in try/catch.
209	 */
210	export async function mcGetDkim(domain: string): Promise<string | null> {
211	  const res = await mcRequest("GET", `/get/dkim/${encodeURIComponent(domain)}`);
212	  if (!res || typeof res !== "object") return null;
213	  // Mailcow returns {} for a domain with no key configured.
214	  const txt = (res as { dkim_txt?: unknown }).dkim_txt;
215	  if (typeof txt === "string" && txt.trim()) return txt.trim();
216	  return null;
217	}
