219	// ---------- Analytics ----------
220	
221	export type MailStats = {
222	  configured: true;
223	  domains: number;
224	  mailboxes: number;
225	  postfix: {
226	    sampled: number;
227	    sent: number;
228	    deferred: number;
229	    bounced: number;
230	    rejected: number;
231	    other: number;
232	  };
233	  rspamd: {
234	    sampled: number;
235	    actions: Record<string, number>;
236	    spam: number; // reject + add header + rewrite subject
237	    clean: number; // no action + greylist / soft reject
238	  };
239	};
240	
241	function asArray(v: unknown): unknown[] {
242	  if (Array.isArray(v)) return v;
243	  if (v && typeof v === "object" && Array.isArray((v as { rows?: unknown[] }).rows)) {
244	    return (v as { rows: unknown[] }).rows;
245	  }
246	  return [];
247	}
248	
249	/**
250	 * Pull recent postfix + rspamd logs and domain/mailbox counts for the admin
251	 * deliverability view. Throws (MailcowError) if not configured or unreachable —
252	 * the admin page catches that and shows a graceful fallback.
253	 */
254	export async function mcStats(sample = 400): Promise<MailStats> {
255	  config(); // throws early with a clear message if not configured
256	
257	  const [domainsRaw, mailboxesRaw, postfixRaw, rspamdRaw] = await Promise.all([
258	    mcRequest("GET", "/get/domain/all").catch(() => []),
259	    mcRequest("GET", "/get/mailbox/all").catch(() => []),
260	    mcRequest("GET", `/get/logs/postfix/${sample}`).catch(() => []),
261	    mcRequest("GET", `/get/logs/rspamd-history/${sample}`).catch(() => []),
262	  ]);
263	
264	  const postfixLogs = asArray(postfixRaw);
265	  const postfix = { sampled: postfixLogs.length, sent: 0, deferred: 0, bounced: 0, rejected: 0, other: 0 };
266	  for (const entry of postfixLogs) {
267	    const msg = String(
268	      (entry as { message?: unknown })?.message ??
269	        (entry && typeof entry === "object" ? JSON.stringify(entry) : entry) ??
270	        "",
271	    ).toLowerCase();
272	    if (msg.includes("status=sent")) postfix.sent++;
273	    else if (msg.includes("status=deferred")) postfix.deferred++;
274	    else if (msg.includes("status=bounced")) postfix.bounced++;
275	    else if (msg.includes("reject:") || msg.includes("status=reject")) postfix.rejected++;
276	    else postfix.other++;
277	  }
278	
279	  const rspamdLogs = asArray(rspamdRaw);
280	  const actions: Record<string, number> = {};
281	  let spam = 0;
282	  let clean = 0;
283	  for (const entry of rspamdLogs) {
284	    const action = String((entry as { action?: unknown })?.action ?? "unknown").toLowerCase();
285	    actions[action] = (actions[action] ?? 0) + 1;
286	    if (action === "reject" || action === "add header" || action === "rewrite subject") spam++;
287	    else clean++;
288	  }
289	
290	  return {
291	    configured: true,
292	    domains: asArray(domainsRaw).length,
293	    mailboxes: asArray(mailboxesRaw).length,
294	    postfix,
295	    rspamd: { sampled: rspamdLogs.length, actions, spam, clean },
296	  };
297	}
