7	export type ComposeDraft = {
8	  mode: "new" | "reply" | "replyAll" | "forward";
9	  to: string;
10	  cc: string;
11	  subject: string;
12	  body: string; // plaintext the user edits
13	  quotedHtml?: string; // quoted original, appended below the reply
14	  inReplyToUid?: number;
15	  replyFolder?: string;
16	};
17	
18	export function Composer({
19	  draft,
20	  onClose,
21	  onSend,
22	}: {
23	  draft: ComposeDraft;
24	  onClose: () => void;
25	  onSend: (payload: SendPayload) => Promise<void>;
26	}) {
27	  const [to, setTo] = useState(draft.to);
28	  const [cc, setCc] = useState(draft.cc);
29	  const [showCc, setShowCc] = useState(!!draft.cc);
30	  const [subject, setSubject] = useState(draft.subject);
31	  const [body, setBody] = useState(draft.body);
32	  const [sending, setSending] = useState(false);
33	  const [error, setError] = useState<string | null>(null);
34	
35	  useEffect(() => {
36	    const onKey = (e: KeyboardEvent) => {
37	      if (e.key === "Escape" && !sending) onClose();
38	      if ((e.metaKey || e.ctrlKey) && e.key === "Enter") void submit();
39	    };
40	    window.addEventListener("keydown", onKey);
41	    return () => window.removeEventListener("keydown", onKey);
42	    // eslint-disable-next-line react-hooks/exhaustive-deps
43	  }, [to, cc, subject, body, sending]);
44	
45	  const title =
46	    draft.mode === "new" ? "New message" : draft.mode === "forward" ? "Forward" : "Reply";
47	
48	  async function submit() {
49	    if (sending) return;
50	    if (!to.trim()) {
51	      setError("Add at least one recipient.");
52	      return;
53	    }
54	    setError(null);
55	    setSending(true);
56	    try {
57	      // Compose the outgoing body. User text becomes both the text part and,
58	      // combined with any quoted original, a simple HTML part.
59	      const escaped = body
60	        .replace(/&/g, "&amp;")
61	        .replace(/</g, "&lt;")
62	        .replace(/>/g, "&gt;");
63	      const htmlBody =
64	        `<div style="white-space:pre-wrap;font-family:-apple-system,Segoe UI,Roboto,sans-serif;font-size:14px;line-height:1.6;color:#1e293b">${escaped}</div>` +
65	        (draft.quotedHtml
66	          ? `<br><blockquote style="margin:0 0 0 12px;padding-left:12px;border-left:3px solid #e2e8f0;color:#64748b">${draft.quotedHtml}</blockquote>`
67	          : "");
68	
69	      await onSend({
70	        to: to.trim(),
71	        cc: cc.trim() || undefined,
72	        subject: subject.trim() || "(no subject)",
73	        text: body,
74	        html: htmlBody,
75	        inReplyToUid: draft.inReplyToUid,
76	        replyFolder: draft.replyFolder,
77	      });
78	      onClose();
79	    } catch (e) {
80	      setError(e instanceof Error ? e.message : "Failed to send. Please try again.");
81	      setSending(false);
82	    }
83	  }
84	
85	  return (
86	    <div className="fixed inset-0 z-50 flex items-end justify-center bg-navy-950/70 p-0 backdrop-blur-sm sm:items-center sm:p-4" role="dialog" aria-modal="true" aria-label={title}>
87	      <div
88	        className="glass flex h-[85vh] w-full max-w-2xl flex-col overflow-hidden shadow-2xl animate-fade-up sm:h-auto sm:max-h-[85vh]"
89	        onClick={(e) => e.stopPropagation()}
90	      >
91	        {/* Header */}
92	        <div className="flex items-center justify-between border-b border-white/[0.08] bg-white/[0.03] px-5 py-3">
93	          <h3 className="flex items-center gap-2 text-sm font-semibold text-white">
94	            <span className="text-brand-300"><Icon.compose size={16} /></span>
95	            {title}
96	          </h3>
97	          <button onClick={onClose} className="btn-ghost rounded-lg p-1.5" aria-label="Close">
98	            <Icon.close size={16} />
99	          </button>
100	        </div>
101	
102	        {/* Fields */}
103	        <div className="flex-1 overflow-y-auto">
104	          <FieldRow label="To">
105	            <input
106	              autoFocus={draft.mode !== "reply" && draft.mode !== "replyAll"}
107	              value={to}
108	              onChange={(e) => setTo(e.target.value)}
109	              placeholder="name@example.com, another@example.com"
110	              className="w-full bg-transparent text-sm text-slate-100 outline-none placeholder:text-slate-600"
111	            />
112	            {!showCc && (
113	              <button onClick={() => setShowCc(true)} className="ml-2 flex-none text-xs font-medium text-slate-500 hover:text-brand-300">
114	                Cc
115	              </button>
116	            )}
117	          </FieldRow>
118	
119	          {showCc && (
120	            <FieldRow label="Cc">
121	              <input
122	                value={cc}
123	                onChange={(e) => setCc(e.target.value)}
124	                placeholder="cc@example.com"
125	                className="w-full bg-transparent text-sm text-slate-100 outline-none placeholder:text-slate-600"
126	              />
127	            </FieldRow>
128	          )}
129	
130	          <FieldRow label="Subject">
131	            <input
132	              value={subject}
133	              onChange={(e) => setSubject(e.target.value)}
134	              placeholder="Subject"
135	              className="w-full bg-transparent text-sm text-slate-100 outline-none placeholder:text-slate-600"
136	            />
137	          </FieldRow>
138	
139	          <textarea
140	            autoFocus={draft.mode === "reply" || draft.mode === "replyAll"}
141	            value={body}
142	            onChange={(e) => setBody(e.target.value)}
143	            placeholder="Write your message…"
144	            className="min-h-[16rem] w-full flex-1 resize-none bg-transparent px-5 py-4 text-sm leading-relaxed text-slate-100 outline-none placeholder:text-slate-600"
145	          />
146	
147	          {draft.quotedHtml && (
148	            <p className="px-5 pb-4 text-xs text-slate-600">
149	              — the original message is quoted below your reply —
150	            </p>
151	          )}
152	        </div>
153	
154	        {/* Footer */}
155	        <div className="flex items-center justify-between gap-3 border-t border-white/[0.08] bg-white/[0.02] px-5 py-3">
156	          <div className="min-w-0 text-xs text-red-300">{error}</div>
157	          <div className="flex flex-none items-center gap-2">
158	            <span className="hidden text-[11px] text-slate-600 sm:inline">
159	              <span className="kbd">⌘/Ctrl</span> + <span className="kbd">Enter</span>
160	            </span>
161	            <button onClick={onClose} className="btn-secondary" disabled={sending}>
162	              Discard
163	            </button>
164	            <button onClick={submit} className="btn-primary" disabled={sending || !to.trim()}>
165	              {sending ? "Sending…" : "Send"}
166	            </button>
167	          </div>
168	        </div>
169	      </div>
170	    </div>
171	  );
172	}
173	
