176	    <label className="flex items-center gap-3 border-b border-white/[0.06] px-5 py-2.5">
177	      <span className="w-14 flex-none text-xs font-medium uppercase tracking-wide text-slate-500">{label}</span>
178	      <span className="flex flex-1 items-center">{children}</span>
179	    </label>
180	  );
181	}
