// ---------- Aliases ----------

/** A mail alias as returned by Mailcow, narrowed to the fields the UI needs. */
export type MailcowAlias = {
  id: number;
  address: string; // the alias address (what mail is sent to)
  goto: string; // destination(s), comma-separated
  active: boolean;
  domain?: string;
};

/** Coerce Mailcow's mixed number/string `active` flag to a boolean. */
function toActive(v: unknown): boolean {
  return v === 1 || v === "1" || v === true;
}

/**
 * List all aliases configured on a domain (`GET /get/alias/all/<domain>`).
 * Mailcow returns an array of alias objects; a domain with no aliases yields an
 * empty array (or `{}`), which we normalise to `[]`.
 */
export async function mcListAliases(domain: string): Promise<MailcowAlias[]> {
  const res = await mcRequest("GET", `/get/alias/all/${encodeURIComponent(domain)}`);
  const rows = Array.isArray(res) ? res : [];
  const out: MailcowAlias[] = [];
  for (const r of rows) {
    if (!r || typeof r !== "object") continue;
    const o = r as Record<string, unknown>;
    const id = Number(o.id);
    const address = typeof o.address === "string" ? o.address : "";
    if (!Number.isFinite(id) || !address) continue;
    out.push({
      id,
      address,
      goto: typeof o.goto === "string" ? o.goto : "",
      active: toActive(o.active),
      domain: typeof o.domain === "string" ? o.domain : undefined,
    });
  }
  return out;
}

/**
 * Create an alias (`POST /add/alias`). `goto` is the destination address (or a
 * comma-separated list) mail to `address` should be delivered to. Throws a
 * MailcowError on any logical failure (e.g. the alias already exists).
 */
export async function mcAddAlias(address: string, goto: string): Promise<unknown> {
  return mcRequest("POST", "/add/alias", {
    address,
    goto,
    active: "1",
  });
}

/** Delete an alias by its Mailcow id (`POST /delete/alias` with `[id]`). */
export async function mcDeleteAlias(id: number): Promise<unknown> {
  return mcRequest("POST", "/delete/alias", [id]);
}

