"use server";

// Server actions for the native webmail "Mailbox settings" panel
// (components/customer/mail/MailSettings.tsx, opened from the FolderRail).
//
// Every action authenticates the caller and resolves ONLY a mailbox they own via
// `resolveMailbox` (which also performs the ownership check used everywhere else
// in the mail client). Writes are rate-limited and return a friendly
// `{ ok, error }`. Alias operations additionally verify the target domain is one
// the caller actually owns (an EmailSubscription) before touching Mailcow.

import { db } from "@/lib/db";
import { checkRateLimit } from "@/lib/rate-limit";
import { resolveMailbox } from "@/lib/mail/imap";
import {
  mailcowConfigured,
  mcListAliases,
  mcAddAlias,
  mcDeleteAlias,
  type MailcowAlias,
} from "@/lib/mailcow";
import { resetMailboxPassword } from "@/lib/actions-email-hosting";

export type Result = { ok: boolean; error?: string };

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

/** Serialisable mailbox settings the panel reads/writes. */
export type MailboxSettings = {
  address: string;
  domain: string;
  displayName: string;
  signature: string;
  autoReplyEnabled: boolean;
  autoReplySubject: string;
  autoReplyBody: string;
};

function domainOf(address: string): string {
  const at = address.lastIndexOf("@");
  return at >= 0 ? address.slice(at + 1).toLowerCase() : "";
}

/** Rate-limit gate returning a friendly `{ ok:false }` instead of throwing. */
function gate(key: string, max: number, windowMs: number): Result | null {
  const r = checkRateLimit(key, { max, windowMs });
  if (!r.ok) return { ok: false, error: `Too many requests — wait ${r.retryAfterSec}s and try again.` };
  return null;
}

/** The domains the signed-in user owns (from their email subscriptions). */
async function ownedDomains(userId: string): Promise<Set<string>> {
  const subs = await db.emailSubscription.findMany({
    where: { userId },
    select: { domainName: true },
  });
  return new Set(subs.map((s) => s.domainName.trim().toLowerCase()).filter(Boolean));
}

// ---------------------------------------------------------------------------
// Identity, signature, auto-reply (stored on the Mailbox row)
// ---------------------------------------------------------------------------

/** Load the current settings for a mailbox the caller owns. */
export async function getMailboxSettings(mailboxAddress?: string): Promise<MailboxSettings> {
  const { mailboxId, address } = await resolveMailbox(mailboxAddress);
  const row = await db.mailbox.findUnique({ where: { id: mailboxId } });
  return {
    address,
    domain: domainOf(address),
    displayName: row?.displayName ?? "",
    signature: row?.signature ?? "",
    autoReplyEnabled: row?.autoReplyEnabled ?? false,
    autoReplySubject: row?.autoReplySubject ?? "",
    autoReplyBody: row?.autoReplyBody ?? "",
  };
}

/** Save the display name + signature onto the mailbox row. */
export async function saveMailboxSettings(
  input: { displayName?: string; signature?: string },
  mailboxAddress?: string,
): Promise<Result> {
  const { user, mailboxId } = await resolveMailbox(mailboxAddress);
  const limited = gate(`mail:settings:${user.id}`, 30, 60_000);
  if (limited) return limited;

  const displayName = (input.displayName ?? "").trim();
  const signature = input.signature ?? "";
  if (displayName.length > 120) return { ok: false, error: "Display name is too long (max 120 characters)." };
  if (signature.length > 5000) return { ok: false, error: "Signature is too long (max 5000 characters)." };

  await db.mailbox.update({
    where: { id: mailboxId },
    data: { displayName: displayName || null, signature: signature.trim() ? signature : null },
  });
  return { ok: true };
}

/**
 * Save the auto-reply / vacation responder onto the mailbox row.
 *
 * NOTE: this is STORE-ONLY. Mailcow's REST API exposes no reliable
 * vacation/auto-responder endpoint (auto-replies live in SOGo user preferences,
 * not the admin API), so we persist the settings and the UI labels them as
 * "saved; server-side delivery is rolling out". We do NOT pretend the mail
 * server sends them.
 */
export async function saveAutoReply(
  input: { enabled: boolean; subject?: string; body?: string },
  mailboxAddress?: string,
): Promise<Result> {
  const { user, mailboxId } = await resolveMailbox(mailboxAddress);
  const limited = gate(`mail:settings:${user.id}`, 30, 60_000);
  if (limited) return limited;

  const enabled = Boolean(input.enabled);
  const subject = (input.subject ?? "").trim();
  const body = (input.body ?? "").trim();
  if (subject.length > 200) return { ok: false, error: "Subject is too long (max 200 characters)." };
  if (body.length > 5000) return { ok: false, error: "Message is too long (max 5000 characters)." };
  if (enabled && !body) return { ok: false, error: "Add an auto-reply message before turning it on." };

  await db.mailbox.update({
    where: { id: mailboxId },
    data: {
      autoReplyEnabled: enabled,
      autoReplySubject: subject || null,
      autoReplyBody: body || null,
    },
  });
  return { ok: true };
}

// ---------------------------------------------------------------------------
// Aliases (Mailcow)
// ---------------------------------------------------------------------------

export type AliasRow = { id: number; address: string; goto: string; active: boolean };

function toAliasRows(list: MailcowAlias[]): AliasRow[] {
  return list.map((a) => ({ id: a.id, address: a.address, goto: a.goto, active: a.active }));
}

/** List the aliases on the mailbox's domain. */
export async function listAliases(
  mailboxAddress?: string,
): Promise<{ ok: boolean; error?: string; aliases: AliasRow[] }> {
  const { user, address } = await resolveMailbox(mailboxAddress);
  const domain = domainOf(address);
  if (!mailcowConfigured()) return { ok: false, error: "Mail server is not configured yet.", aliases: [] };

  const owned = await ownedDomains(user.id);
  if (!owned.has(domain)) return { ok: false, error: "You don't own this mailbox's domain.", aliases: [] };

  try {
    const list = await mcListAliases(domain);
    return { ok: true, aliases: toAliasRows(list) };
  } catch (e) {
    return { ok: false, error: friendly(e), aliases: [] };
  }
}

/**
 * Add an alias on a domain the caller owns. `alias` may be a full address or a
 * bare local part (the mailbox's own domain is assumed). `goto` defaults to the
 * mailbox itself.
 */
export async function addAlias(alias: string, goto?: string, mailboxAddress?: string): Promise<Result> {
  const { user, address } = await resolveMailbox(mailboxAddress);
  const limited = gate(`mail:alias:${user.id}`, 20, 60_000);
  if (limited) return limited;
  if (!mailcowConfigured()) return { ok: false, error: "Mail server is not configured yet." };

  let aliasAddr = (alias ?? "").trim().toLowerCase();
  if (!aliasAddr) return { ok: false, error: "Enter an alias address." };
  // Accept a bare local part — assume the mailbox's own domain.
  if (!aliasAddr.includes("@")) aliasAddr = `${aliasAddr}@${domainOf(address)}`;
  if (!EMAIL_RE.test(aliasAddr)) return { ok: false, error: "That doesn't look like a valid email address." };

  const owned = await ownedDomains(user.id);
  if (!owned.has(domainOf(aliasAddr))) {
    return { ok: false, error: "You can only add aliases on a domain you own." };
  }

  const dest = (goto ?? "").trim() || address;
  if (!EMAIL_RE.test(dest)) return { ok: false, error: "The destination address is not valid." };
  if (dest.toLowerCase() === aliasAddr) return { ok: false, error: "An alias can't point to itself." };

  try {
    await mcAddAlias(aliasAddr, dest);
    return { ok: true };
  } catch (e) {
    return { ok: false, error: friendly(e) };
  }
}

/** Remove an alias by id, after verifying it lives on a domain the caller owns. */
export async function removeAlias(id: number, mailboxAddress?: string): Promise<Result> {
  const { user, address } = await resolveMailbox(mailboxAddress);
  const limited = gate(`mail:alias:${user.id}`, 20, 60_000);
  if (limited) return limited;
  if (!mailcowConfigured()) return { ok: false, error: "Mail server is not configured yet." };
  if (!Number.isFinite(id)) return { ok: false, error: "Invalid alias." };

  const domain = domainOf(address);
  const owned = await ownedDomains(user.id);
  if (!owned.has(domain)) return { ok: false, error: "You don't own this mailbox's domain." };

  try {
    // Confirm the alias belongs to this owned domain before deleting.
    const list = await mcListAliases(domain);
    const match = list.find((a) => a.id === id);
    if (!match) return { ok: false, error: "That alias no longer exists on your domain." };
    await mcDeleteAlias(id);
    return { ok: true };
  } catch (e) {
    return { ok: false, error: friendly(e) };
  }
}

// ---------------------------------------------------------------------------
// Change password (reuses the owner-checked, rate-limited hosting action)
// ---------------------------------------------------------------------------

/** Reset the mailbox password; returns the new password once for the customer. */
export async function resetPassword(
  mailboxAddress?: string,
): Promise<{ error?: string; password?: string }> {
  const { mailboxId } = await resolveMailbox(mailboxAddress);
  return resetMailboxPassword(mailboxId);
}

/** Turn a thrown error into a short, safe message for the UI. */
function friendly(e: unknown): string {
  const msg = e instanceof Error ? e.message : String(e);
  return msg.replace(/\s+/g, " ").slice(0, 200) || "Something went wrong. Please try again.";
}

"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import {
  getMailboxSettings,
  saveMailboxSettings,
  saveAutoReply,
  listAliases,
  addAlias,
  removeAlias,
  resetPassword,
  type MailboxSettings,
  type AliasRow,
} from "@/lib/actions-mailbox-settings";
import { Icon } from "./util";

/** Mail server endpoints shown in the "configure your device" panel. */
const MAIL_HOST = "mail.nxeon.cloud";

type Section = "identity" | "connection" | "aliases" | "autoreply" | "password";

const SECTIONS: { key: Section; label: string; icon: keyof typeof Icon }[] = [
  { key: "identity", label: "Identity & signature", icon: "user" },
  { key: "connection", label: "Connection details", icon: "mail" },
  { key: "aliases", label: "Aliases", icon: "tag" },
  { key: "autoreply", label: "Auto-reply", icon: "reply" },
  { key: "password", label: "Change password", icon: "cog" },
];

export function MailSettings({
  mailboxAddress,
  onClose,
  onSignatureSaved,
}: {
  mailboxAddress?: string;
  onClose: () => void;
  /** Notify the parent so a freshly-saved signature/display name applies immediately. */
  onSignatureSaved?: (s: { signature: string; displayName: string }) => void;
}) {
  const [section, setSection] = useState<Section>("identity");
  const [settings, setSettings] = useState<MailboxSettings | null>(null);
  const [loadError, setLoadError] = useState<string | null>(null);

  useEffect(() => {
    let alive = true;
    setSettings(null);
    setLoadError(null);
    getMailboxSettings(mailboxAddress)
      .then((s) => alive && setSettings(s))
      .catch((e) => alive && setLoadError(e instanceof Error ? e.message : "Couldn't load settings."));
    return () => {
      alive = false;
    };
  }, [mailboxAddress]);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);

  return (
    <div
      className="fixed inset-0 z-50 flex items-end justify-center bg-navy-950/70 p-0 backdrop-blur-sm sm:items-center sm:p-4"
      role="dialog"
      aria-modal="true"
      aria-label="Mailbox settings"
      onClick={onClose}
    >
      <div
        className="glass flex h-[88vh] w-full max-w-3xl flex-col overflow-hidden shadow-2xl animate-fade-up sm:h-[80vh]"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="flex items-center justify-between border-b border-white/[0.08] bg-white/[0.03] px-5 py-3">
          <div className="min-w-0">
            <h3 className="flex items-center gap-2 text-sm font-semibold text-white">
              <span className="text-brand-300"><Icon.cog size={16} /></span>
              Mailbox settings
            </h3>
            {settings && (
              <p className="mt-0.5 truncate text-xs text-slate-500" title={settings.address}>
                {settings.address}
              </p>
            )}
          </div>
          <button onClick={onClose} className="btn-ghost rounded-lg p-1.5" aria-label="Close">
            <Icon.close size={16} />
          </button>
        </div>

        <div className="flex min-h-0 flex-1 flex-col sm:flex-row">
          {/* Section nav */}
          <nav className="flex flex-none gap-1 overflow-x-auto border-b border-white/[0.06] p-2 sm:w-52 sm:flex-col sm:overflow-x-visible sm:overflow-y-auto sm:border-b-0 sm:border-r">
            {SECTIONS.map((s) => {
              const Ico = Icon[s.icon];
              const active = section === s.key;
              return (
                <button
                  key={s.key}
                  onClick={() => setSection(s.key)}
                  className={`flex flex-none items-center gap-2.5 whitespace-nowrap rounded-xl px-3 py-2 text-sm font-medium transition-colors ${
                    active ? "nav-item-active" : "text-slate-400 hover:bg-white/[0.05] hover:text-white"
                  }`}
                >
                  <Ico size={16} className={active ? "text-white" : ""} />
                  <span className="hidden sm:inline">{s.label}</span>
                  <span className="sm:hidden">{s.label.split(" ")[0]}</span>
                </button>
              );
            })}
          </nav>

          {/* Section content */}
          <div className="min-h-0 flex-1 overflow-y-auto p-5">
            {loadError ? (
              <ErrorNote text={loadError} />
            ) : !settings ? (
              <LoadingRows />
            ) : section === "identity" ? (
              <IdentitySection
                mailboxAddress={mailboxAddress}
                initial={settings}
                onSaved={(displayName, signature) => {
                  setSettings((cur) => (cur ? { ...cur, displayName, signature } : cur));
                  onSignatureSaved?.({ displayName, signature });
                }}
              />
            ) : section === "connection" ? (
              <ConnectionSection address={settings.address} />
            ) : section === "aliases" ? (
              <AliasesSection mailboxAddress={mailboxAddress} domain={settings.domain} />
            ) : section === "autoreply" ? (
              <AutoReplySection
                mailboxAddress={mailboxAddress}
                initial={settings}
                onSaved={(v) => setSettings((cur) => (cur ? { ...cur, ...v } : cur))}
              />
            ) : (
              <PasswordSection mailboxAddress={mailboxAddress} />
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

/* -------------------------------------------------------------------------- */
/* Section: Identity & signature                                               */
/* -------------------------------------------------------------------------- */

function IdentitySection({
  mailboxAddress,
  initial,
  onSaved,
}: {
  mailboxAddress?: string;
  initial: MailboxSettings;
  onSaved: (displayName: string, signature: string) => void;
}) {
  const [displayName, setDisplayName] = useState(initial.displayName);
  const [signature, setSignature] = useState(initial.signature);
  const [saving, setSaving] = useState(false);
  const [msg, setMsg] = useState<string | null>(null);
  const [err, setErr] = useState<string | null>(null);

  async function save() {
    setSaving(true);
    setMsg(null);
    setErr(null);
    try {
      const res = await saveMailboxSettings({ displayName, signature }, mailboxAddress);
      if (!res.ok) setErr(res.error || "Couldn't save.");
      else {
        setMsg("Saved.");
        onSaved(displayName.trim(), signature);
      }
    } catch (e) {
      setErr(e instanceof Error ? e.message : "Couldn't save.");
    } finally {
      setSaving(false);
    }
  }

  return (
    <div className="space-y-5">
      <SectionHead
        title="Identity & signature"
        sub="Your name and signature appear on messages you send from this mailbox."
      />
      <div>
        <label className="label" htmlFor="ms-name">Display name</label>
        <input
          id="ms-name"
          className="input"
          value={displayName}
          onChange={(e) => setDisplayName(e.target.value)}
          placeholder="e.g. Jane Doe"
          maxLength={120}
        />
      </div>
      <div>
        <label className="label" htmlFor="ms-sig">Signature</label>
        <textarea
          id="ms-sig"
          className="input min-h-[9rem] resize-y font-mono leading-relaxed"
          value={signature}
          onChange={(e) => setSignature(e.target.value)}
          placeholder={"— \nJane Doe\nAcme Inc."}
          maxLength={5000}
        />
        <p className="mt-1.5 text-xs text-slate-500">
          Added below a separator on new messages, and beneath the quoted text on replies.
        </p>
      </div>
      <SaveRow saving={saving} msg={msg} err={err} onSave={save} />
    </div>
  );
}

/* -------------------------------------------------------------------------- */
/* Section: Connection details                                                 */
/* -------------------------------------------------------------------------- */

function ConnectionSection({ address }: { address: string }) {
  return (
    <div className="space-y-5">
      <SectionHead
        title="Connection details"
        sub="Use these to set up this mailbox in Outlook, Apple Mail, Thunderbird or any other mail app."
      />

      <div className="space-y-3">
        <p className="section-label">Incoming — IMAP</p>
        <div className="grid gap-2 sm:grid-cols-2">
          <CopyField label="Server" value={MAIL_HOST} />
          <CopyField label="Port" value="993" />
          <CopyField label="Security" value="SSL / TLS" copyable={false} />
          <CopyField label="Username" value={address} />
        </div>
      </div>

      <div className="space-y-3">
        <p className="section-label">Outgoing — SMTP</p>
        <div className="grid gap-2 sm:grid-cols-2">
          <CopyField label="Server" value={MAIL_HOST} />
          <CopyField label="Port" value="587" />
          <CopyField label="Security" value="STARTTLS" copyable={false} />
          <CopyField label="Username" value={address} />
        </div>
      </div>

      <div className="rounded-xl border border-white/[0.08] bg-white/[0.02] px-4 py-3 text-xs text-slate-400">
        <span className="font-medium text-slate-300">Password:</span> use your mailbox password. If you
        don't have it, set a new one under <span className="text-slate-300">Change password</span>.
      </div>
    </div>
  );
}

/* -------------------------------------------------------------------------- */
/* Section: Aliases                                                            */
/* -------------------------------------------------------------------------- */

function AliasesSection({ mailboxAddress, domain }: { mailboxAddress?: string; domain: string }) {
  const [aliases, setAliases] = useState<AliasRow[] | null>(null);
  const [loadErr, setLoadErr] = useState<string | null>(null);
  const [newAlias, setNewAlias] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);

  const load = useCallback(async () => {
    setLoadErr(null);
    try {
      const res = await listAliases(mailboxAddress);
      if (!res.ok) {
        setLoadErr(res.error || "Couldn't load aliases.");
        setAliases([]);
      } else {
        setAliases(res.aliases);
      }
    } catch (e) {
      setLoadErr(e instanceof Error ? e.message : "Couldn't load aliases.");
      setAliases([]);
    }
  }, [mailboxAddress]);

  useEffect(() => {
    void load();
  }, [load]);

  async function add() {
    const val = newAlias.trim();
    if (!val) return;
    setBusy(true);
    setErr(null);
    try {
      const res = await addAlias(val, undefined, mailboxAddress);
      if (!res.ok) setErr(res.error || "Couldn't add alias.");
      else {
        setNewAlias("");
        await load();
      }
    } catch (e) {
      setErr(e instanceof Error ? e.message : "Couldn't add alias.");
    } finally {
      setBusy(false);
    }
  }

  async function remove(id: number) {
    setErr(null);
    // Optimistic removal.
    setAliases((cur) => (cur ? cur.filter((a) => a.id !== id) : cur));
    try {
      const res = await removeAlias(id, mailboxAddress);
      if (!res.ok) {
        setErr(res.error || "Couldn't remove alias.");
        await load();
      }
    } catch (e) {
      setErr(e instanceof Error ? e.message : "Couldn't remove alias.");
      await load();
    }
  }

  return (
    <div className="space-y-5">
      <SectionHead
        title="Aliases"
        sub={`Extra addresses on ${domain || "your domain"} that deliver to this mailbox.`}
      />

      {/* Add form */}
      <div className="flex flex-col gap-2 sm:flex-row">
        <div className="flex flex-1 items-stretch overflow-hidden rounded-xl border border-white/10 bg-navy-900/80 focus-within:border-brand-400/60 focus-within:ring-2 focus-within:ring-brand-500/20">
          <input
            className="min-w-0 flex-1 bg-transparent px-3.5 py-2.5 text-sm text-slate-100 outline-none placeholder:text-slate-500"
            value={newAlias}
            onChange={(e) => setNewAlias(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") void add();
            }}
            placeholder="sales"
            aria-label="New alias"
          />
          {!newAlias.includes("@") && domain && (
            <span className="flex flex-none items-center pr-3 text-sm text-slate-500">@{domain}</span>
          )}
        </div>
        <button className="btn-primary flex-none" onClick={add} disabled={busy || !newAlias.trim()}>
          {busy ? "Adding…" : "Add alias"}
        </button>
      </div>
      {err && <ErrorNote text={err} />}

      {/* List */}
      {aliases === null ? (
        <LoadingRows rows={3} />
      ) : loadErr ? (
        <ErrorNote text={loadErr} />
      ) : aliases.length === 0 ? (
        <EmptyNote text="No aliases yet. Add one above to start forwarding another address into this mailbox." />
      ) : (
        <ul className="divide-y divide-white/[0.06] overflow-hidden rounded-xl border border-white/[0.06]">
          {aliases.map((a) => (
            <li key={a.id} className="flex items-center gap-3 px-4 py-2.5">
              <span className="text-brand-300"><Icon.tag size={15} /></span>
              <div className="min-w-0 flex-1">
                <p className="truncate font-mono text-sm text-slate-100">{a.address}</p>
                <p className="truncate text-xs text-slate-500">→ {a.goto || "—"}</p>
              </div>
              {!a.active && <span className="flex-none text-[11px] text-amber-300">inactive</span>}
              <button
                onClick={() => remove(a.id)}
                className="btn-ghost flex-none rounded-lg p-1.5 text-slate-500 hover:text-red-300"
                aria-label={`Remove alias ${a.address}`}
                title="Remove alias"
              >
                <Icon.trash size={15} />
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

