function AutoReplySection({
  mailboxAddress,
  initial,
  onSaved,
}: {
  mailboxAddress?: string;
  initial: MailboxSettings;
  onSaved: (v: { autoReplyEnabled: boolean; autoReplySubject: string; autoReplyBody: string }) => void;
}) {
  const [enabled, setEnabled] = useState(initial.autoReplyEnabled);
  const [subject, setSubject] = useState(initial.autoReplySubject);
  const [body, setBody] = useState(initial.autoReplyBody);
  const [saving, setSaving] = useState(false);
  const [msg, setMsg] = useState<string | null>(null);
  const [err, setErr] = useState<string | null>(null);

  async function save() {
    setSaving(true);
    setMsg(null);
    setErr(null);
    try {
      const res = await saveAutoReply({ enabled, subject, body }, mailboxAddress);
      if (!res.ok) setErr(res.error || "Couldn't save.");
      else {
        setMsg("Saved.");
        onSaved({ autoReplyEnabled: enabled, autoReplySubject: subject.trim(), autoReplyBody: body.trim() });
      }
    } catch (e) {
      setErr(e instanceof Error ? e.message : "Couldn't save.");
    } finally {
      setSaving(false);
    }
  }

  return (
    <div className="space-y-5">
      <SectionHead
        title="Auto-reply"
        sub="Send an automatic response to incoming messages while you're away."
      />

      <button
        type="button"
        onClick={() => setEnabled((v) => !v)}
        className="flex w-full items-center justify-between rounded-xl border border-white/[0.08] bg-white/[0.02] px-4 py-3 text-left transition-colors hover:border-white/20"
      >
        <span className="text-sm font-medium text-slate-200">Auto-reply {enabled ? "on" : "off"}</span>
        <span
          className={`relative h-6 w-11 flex-none rounded-full transition-colors ${enabled ? "bg-brand-500" : "bg-white/10"}`}
        >
          <span
            className={`absolute top-0.5 h-5 w-5 rounded-full bg-white shadow transition-transform ${enabled ? "translate-x-[22px]" : "translate-x-0.5"}`}
          />
        </span>
      </button>

      <div className={enabled ? "space-y-4" : "space-y-4 opacity-50"}>
        <div>
          <label className="label" htmlFor="ar-subject">Subject</label>
          <input
            id="ar-subject"
            className="input"
            value={subject}
            onChange={(e) => setSubject(e.target.value)}
            placeholder="Out of office"
            maxLength={200}
            disabled={!enabled}
          />
        </div>
        <div>
          <label className="label" htmlFor="ar-body">Message</label>
          <textarea
            id="ar-body"
            className="input min-h-[8rem] resize-y leading-relaxed"
            value={body}
            onChange={(e) => setBody(e.target.value)}
            placeholder="Thanks for your email. I'm away until…"
            maxLength={5000}
            disabled={!enabled}
          />
        </div>
      </div>

      <div className="rounded-xl border border-amber-400/20 bg-amber-400/[0.06] px-4 py-3 text-xs text-amber-200/90">
        Auto-reply is saved to your mailbox. Server-side delivery of auto-replies is rolling out — until
        then, these settings are stored but not yet sent automatically.
      </div>

      <SaveRow saving={saving} msg={msg} err={err} onSave={save} />
    </div>
  );
}

